parameters.jsCode:
// FFmpeg compositor via shell exec
// NOTA: n8n cloud puede no permitir spawn de FFmpeg directo.
// Alternativa 1: API externa (Shotstack, Cloudinary, Bannerbear)
// Alternativa 2: Self-hosted helper service
// Alternativa 3: Replicate model que hace video composition

// Por ahora, devolvemos plan de composición + URLs para que un service externo lo ejecute

const brief_id = $('Webhook trigger (from HITL approve)').item.json.body.brief_id;
const keyframes_data = $('A5 Visual Director').item.json.output?.keyframes || $('A5 Visual Director').item.json.keyframes;
const voice_url = `${$env.SUPABASE_URL}/storage/v1/object/public/dinero-ia-assets/voice/${brief_id}/narration.mp3`;
const music_track = $('A8d Music Selection').item.json[0] || {};
const audio_mix = $('A6 Audio Director').item.json.output || $('A6 Audio Director').item.json;

const composition_plan = {
  brief_id,
  output_path: `final/${brief_id}/reel.mp4`,
  video_segments: keyframes_data.map(k => ({
    url: `${$env.SUPABASE_URL}/storage/v1/object/public/dinero-ia-assets/video_segments/${brief_id}/${k.frame_index}.mp4`,
    start: k.start_second,
    end: k.end_second,
    transition_out: k.transition_to_next
  })),
  audio_tracks: [
    {
      url: voice_url,
      type: 'voice',
      volume_lufs: -14,
      priority: 1
    },
    {
      url: music_track.url || null,
      type: 'music',
      volume_lufs: audio_mix.audio_mix_volume_lufs,
      duck_to_lufs: audio_mix.audio_mix_disclaimer_lufs,
      sidechain_from: 'voice',
      priority: 2
    }
  ],
  subtitles: {
    enabled: true,
    style: {
      font_family: 'Inter',
      font_weight: 'Bold',
      font_size_pt: 52,
      color: '#FFFFFF',
      outline_color: '#000000',
      outline_width: 4,
      position: { x: 'center', y: '65%' },
      highlight_color: '#D4A574'
    }
  },
  output_format: {
    width: 1080,
    height: 1920,
    fps: 30,
    codec: 'h264',
    audio_codec: 'aac',
    bitrate_video: '6M',
    bitrate_audio: '192k'
  }
};

return {
  composition_plan,
  status: 'plan_generated_pending_compositor_service'
};
